mapper.select:
select P_Project_Stage as theKey, count(*) as theValue from pre_project where P_Project_Stage is not null and deleted=false and P_Id in
#{id}
group by P_Project_Stage

select con.Con_Name as conName, pro.P_Name as pName, prod.D_Name as pCompetentDepartmentName, dep.D_Name as dName, c1.C_Name as pConstructionUnitName, c1.C_Abbreviation as pConsAbbName, sec.Sec_Name as secName, mn.* from Gantt_Plan mn left join Con_Contract con on con.Con_Id=mn.Con_Id left join Pre_Project pro on pro.P_Id=mn.P_Id left join SYS_Department dep on dep.D_ID=mn.Plan_D_Id left join SYS_Company c1 on pro.P_Construction_Unit=c1.C_Id left join SYS_Department prod on prod.D_Id=pro.P_Competent_Department left join Sec_Info sec on sec.Sec_Id=mn.Sec_Id where mn.Plan_State=7 and mn.P_Id=#{pId}
and mn.Plan_Type in
#{type}

sql.if:
and (mn.Plan_Type not in

    #{exType}

or mn.Plan_Type is null)

mapper.select:
select
con.Con_Name as conName, dep.D_Name as dName, sec.Sec_Name as secName, gpt.Pt_Name as ptName, mn.*, pro.P_Department as pDepartment, d2.D_Name as pDepartmentName, (case when exists(select 1 from Gantt_Plan_Change gpc where gpc.Plan_Source = mn.Plan_Id and gpc.Plan_State != 3 and gpc.Plan_State != 7) then 1 else 0 end) as planChanging, (select count(*) from Gantt_Tasks gt where gt.Plan_Id=mn.Plan_Id and task_importance = '99') as milestoneCount, (select count(*) from Gantt_Tasks gt where gt.Plan_Id=mn.Plan_Id and task_importance = '01') as firstLevelCount, (select count(*) from Gantt_Tasks gt where gt.Plan_Id=mn.Plan_Id and task_importance = '02') as secondLevelCount from Gantt_Plan mn left join Gantt_Plan_Template gpt on gpt.pt_id=mn.pt_id left join Con_Contract con on con.Con_Id=mn.Con_Id left join SYS_Department dep on dep.D_ID=mn.Plan_D_Id
left join SYS_Department d2 on pro.P_Department = d2.D_Id left join Sec_Info sec on sec.Sec_Id=mn.Sec_Id ${params.authSql}
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
ORDER BY CASE mn.plan_state WHEN 3 THEN 99 ELSE mn.plan_state END, CASE WHEN mn.plan_state = 0 THEN mn.plan_create_time ELSE mn.plan_state_time END DESC

select con.Con_Name as conName,
dep.D_Name as dName, sec.Sec_Name as secName, mn.* from Gantt_Plan mn left join Con_Contract con on con.Con_Id=mn.Con_Id
left join SYS_Department dep on dep.D_ID=mn.Plan_D_Id left join Sec_Info sec on sec.Sec_Id=mn.Sec_Id ${params.authSql} and mn.Plan_State=7
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Plan_Create_Time desc

select gs.Gs_Section as gsSection, mn.plan_name as planName, prp.p_id as pId, prp.p_name as pName, prp.P_Competent_Department as pCompetentDepartment, prod.D_Name as pCompetentDepartmentName, prp.P_Category as pCategory, prp.P_Project_Manager as pProjectManager, su1.U_Name as pProjectManagerName, prp.P_Engineer as pEngineer, su2.U_Name as pEngineerName, tk.* from Gantt_Tasks tk left join Gant_Section gs on gs.id=tk.gs_id left join Gantt_Plan mn on mn.plan_id=tk.plan_id and mn.Plan_State=7 left join Pre_Project prp ON prp.P_ID = mn.P_ID left join SYS_Department prod on prod.D_Id=prp.P_Competent_Department left join SYS_User su1 on prp.P_Project_Manager = su1.U_ID left join SYS_User su2 on prp.P_Engineer = su2.U_ID
order by tk.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
ORDER BY tk.Task_End_Date ASC

mapper.sql:
${params.authSql}
and prp.deleted = false
and prp.P_Status = '1'
and (prp.state = 7 or (prp.ppr_id is not null and prp.state != 3))

    AND 1 = 0


    and tk.Task_Type in
    
        #{type}
    


    and tk.Task_Finish_Time is null


    and tk.task_state!=0


    and mn.P_ID=#{params.pId}


    and tk.plan_id=#{params.planId}


    and tk.task_Importance=#{params.taskImportance}


    and INSTR(tk.task_Text,#{params.taskText})


    
        
            and likePname(#{params.pName},prp.P_Id)=true
        
        
            and INSTR(prp.p_name,#{params.pName})
        
    


    
    and (tk.Must_Handle = 0 or tk.Must_Handle is null)


    
    and (tk.Must_Handle = 0 or tk.Must_Handle is null)


    
        
            and (prod.D_Name is null or prod.D_Name = '')
        
        
            and prod.D_Name in
            
                #{pCompetentDepartmentName}
            
        
    


    
        
            and (prp.P_Category is null or prp.P_Category = '')
        
        
            and prp.P_Category in
            
                #{pCategory}
            
        
    


    and prp.P_Category = #{params.pCategory}


    
        
            and (su1.U_Name is null or su1.U_Name = '')
        
        
            and su1.U_Name in
            
                #{pProjectManagerName}
            
        
    


    
        
            and (su2.U_Name is null or su2.U_Name = '')
        
        
            and su2.U_Name in
            
                #{pEngineerName}
            
        
    


    AND EXISTS (
    SELECT 1
    FROM SYS_POSITION_USER_P pup
    LEFT JOIN SYS_POSITION_P pp ON pp.PP_ID = pup.PP_ID
    LEFT JOIN SYS_DEPARTMENT_P dp ON dp.PD_ID = pp.PD_ID
    WHERE pup.U_ID = #{params.uId}
    AND pp.PP_CODE IN
    
        #{code}
    
    AND dp.P_ID = mn.P_ID
    )


    AND 1 = 0


    
        tk.Task_Importance = #{taskImportance}
    


    
        
            
                tk.GS_ID IS NULL
            
            
                tk.GS_ID = #{gsId}

${params.authSql}
and mn.Plan_State = 7
and prp.deleted = false
and prp.P_Status = '1'
and (prp.state = 7 or (prp.ppr_id is not null and prp.state != 3))

    
        
            and  likePname(#{params.pName},prp.P_Id)=true
        
        
            and  prp.P_Name LIKE CONCAT('%',#{params.pName},'%')
        
    


    
        
            and (prod.D_Name is null or prod.D_Name = '')
        
        
            and prod.D_Name in
            
                #{pCompetentDepartmentName}
            
        
    


    
        
            and (prp.P_Category is null or prp.P_Category = '')
        
        
            and prp.P_Category in
            
                #{pCategory}
            
        
    


    and prp.P_Category = #{params.pCategory}


    
        
            and (su1.U_Name is null or su1.U_Name = '')
        
        
            and su1.U_Name in
            
                #{pProjectManagerName}
            
        
    


    
        
            and (su2.U_Name is null or su2.U_Name = '')
        
        
            and su2.U_Name in
            
                #{pEngineerName}
            
        
    


    AND EXISTS (
    SELECT 1
    FROM SYS_POSITION_USER_P pup
    LEFT JOIN SYS_POSITION_P pp ON pp.PP_ID = pup.PP_ID
    LEFT JOIN SYS_DEPARTMENT_P dp ON dp.PD_ID = pp.PD_ID
    WHERE pup.U_ID = #{params.uId}
    AND pp.PP_CODE IN
    
        #{code}
    
    AND dp.P_ID = mn.P_ID
    )

mapper.select:
select
SUM(CASE WHEN (Must_Handle = 0 or Must_Handle is null) and jsDay < 0 then 1 else 0 end) as yqCount, SUM(CASE WHEN Task_Importance='99' and (Must_Handle = 0 or Must_Handle is null) and jsDay>=0 and jsDay<=#{conf.milestone} then 1 else 0 end) as lcbLq, SUM(CASE WHEN Task_Importance='99' and (Must_Handle = 0 or Must_Handle is null) and jsDay < 0 then 1 else 0 end) as lcbYq, SUM(CASE WHEN Task_Importance='01' and (Must_Handle = 0 or Must_Handle is null) and jsDay>=0 and jsDay<=#{conf.firstLevel} then 1 else 0 end) as yjLq, SUM(CASE WHEN Task_Importance='01' and (Must_Handle = 0 or Must_Handle is null) and jsDay < 0 then 1 else 0 end) as yjYq, SUM(CASE WHEN Task_Importance='02' and (Must_Handle = 0 or Must_Handle is null) and jsDay>=0 and jsDay<=#{conf.secondLevel} then 1 else 0 end) as ejLq, SUM(CASE WHEN Task_Importance='02' and (Must_Handle = 0 or Must_Handle is null) and jsDay < 0 then 1 else 0 end) as ejYq from ( select gst.Task_id, gst.Task_Finish_Time, gst.Task_Begin_Time, gst.Task_Start_Date, gst.Task_End_Date, gst.Task_Importance, gst.Task_Type, gst.Must_Handle, (CASE WHEN gst.Task_Begin_Time is null THEN DATEDIFF(CAST(gst.Task_Start_Date as DATE),CAST(now() as DATE)) ELSE DATEDIFF(CAST(gst.Task_End_Date as DATE),CAST(now() as DATE)) END) AS jsDay from gantt_tasks gst left join Gantt_Plan mn on mn.plan_id=gst.plan_id left join Pre_Project prp ON prp.P_ID = mn.P_ID left join SYS_Department prod on prod.D_Id = prp.P_Competent_Department left join SYS_User su1 on prp.P_Project_Manager = su1.U_ID left join SYS_User su2 on prp.P_Engineer = su2.U_ID
) se

select
SUM(CASE WHEN (Must_Handle = 0 or Must_Handle is null) and jsDay < 0 then 1 else 0 end) as yqCount, SUM(CASE WHEN Task_Importance='99' and (Must_Handle = 0 or Must_Handle is null) and jsDay>=0 and jsDay<=#{conf.milestone} then 1 else 0 end) as lcbLq, SUM(CASE WHEN Task_Importance='99' and (Must_Handle = 0 or Must_Handle is null) and jsDay < 0 then 1 else 0 end) as lcbYq, SUM(CASE WHEN Task_Importance='01' and (Must_Handle = 0 or Must_Handle is null) and jsDay>=0 and jsDay<=#{conf.firstLevel} then 1 else 0 end) as yjLq, SUM(CASE WHEN Task_Importance='01' and (Must_Handle = 0 or Must_Handle is null) and jsDay < 0 then 1 else 0 end) as yjYq, SUM(CASE WHEN Task_Importance='02' and (Must_Handle = 0 or Must_Handle is null) and jsDay>=0 and jsDay<=#{conf.secondLevel} then 1 else 0 end) as ejLq, SUM(CASE WHEN Task_Importance='02' and (Must_Handle = 0 or Must_Handle is null) and jsDay < 0 then 1 else 0 end) as ejYq from ( select gst.Task_id, gst.Task_Finish_Time, gst.Task_Begin_Time, gst.Task_Start_Date, gst.Task_End_Date, gst.Task_Importance, gst.Task_Type, gst.Must_Handle, (CASE WHEN gst.Task_Begin_Time is null THEN DATEDIFF(DAY,CAST(now() as DATE),CAST(gst.Task_Start_Date as DATE)) ELSE DATEDIFF(DAY,CAST(now() as DATE),CAST(gst.Task_End_Date as DATE)) END) AS jsDay from gantt_tasks gst left join Gantt_Plan mn on mn.plan_id=gst.plan_id left join Pre_Project prp ON prp.P_ID = mn.P_ID left join SYS_Department prod on prod.D_Id = prp.P_Competent_Department left join SYS_User su1 on prp.P_Project_Manager = su1.U_ID left join SYS_User su2 on prp.P_Engineer = su2.U_ID
) se

mapper.sql:
${authSql} and gst.Task_Finish_Time IS NULL and gst.task_state!=0 and mn.Plan_State = 7 and prp.deleted = false and prp.P_Status = '1' and (prp.state = 7 or (prp.ppr_id is not null and prp.state != 3))
and likePname(#{params.pName},prp.P_Id)=true
and prp.P_Name LIKE CONCAT('%',#{params.pName},'%')
and (prod.D_Name is null or prod.D_Name = '')
and prod.D_Name in
#{pCompetentDepartmentName}
and (prp.P_Category is null or prp.P_Category = '')
and prp.P_Category in
#{pCategory}
and prp.P_Category = #{params.pCategory}
and (su1.U_Name is null or su1.U_Name = '')
and su1.U_Name in
#{pProjectManagerName}
and (su2.U_Name is null or su2.U_Name = '')
and su2.U_Name in
#{pEngineerName}
AND EXISTS( SELECT 1 FROM SYS_POSITION_USER_P pup LEFT JOIN SYS_POSITION_P pp ON pp.PP_ID = pup.PP_ID LEFT JOIN SYS_DEPARTMENT_P dp ON dp.PD_ID = pp.PD_ID WHERE pup.U_ID = #{uId} AND pp.PP_CODE IN
#{code}
AND dp.P_ID = mn.P_ID )

mapper.select:
SELECT count(1) FROM Gantt_Plan mn LEFT JOIN Pre_Project prp ON prp.P_ID = mn.P_ID ${authSql}
and prp.P_Name LIKE CONCAT('%',#{pName},'%')
and mn.Plan_State = 7 and prp.deleted = false and prp.P_Status = '1' and (prp.state = 7 or (prp.ppr_id is not null and prp.state != 3))
AND ( SELECT COUNT(*) FROM SYS_POSITION_USER_P pup LEFT JOIN SYS_POSITION_P pp ON pp.PP_ID = pup.PP_ID LEFT JOIN SYS_DEPARTMENT_P dp ON dp.PD_ID = pp.PD_ID WHERE pup.U_ID = #{uId} AND pp.PP_CODE IN
#{code}
AND dp.P_ID = mn.P_ID ) > 0

SELECT tp_entityid AS plan_id FROM Sys_Task_Processin WHERE tp_acttype = 'userTask' AND tp_user = #{uId}
UNION
SELECT cc_fileid AS plan_id FROM SYS_CarbonCopy WHERE cc_user = #{uId}
UNION
SELECT cp_fileid AS plan_id FROM SYS_CoordinationProcess WHERE cp_user = #{uId}

SELECT
con.Con_Name AS conName, dep.D_Name AS dName, sec.Sec_Name AS secName, gpt.Pt_Name AS ptName, mn.*, pro.P_Department AS pDepartment, d2.D_Name AS pDepartmentName, COALESCE(gtc.milestoneCount, 0) AS milestoneCount, COALESCE(gtc.firstLevelCount, 0) AS firstLevelCount, COALESCE(gtc.secondLevelCount, 0) AS secondLevelCount, CASE WHEN mn.Plan_State = 7 THEN 1 ELSE 0 END AS alreadyOverCount, CASE WHEN mn.Plan_State = 0 THEN 1 ELSE 0 END AS notStartCount, CASE WHEN mn.Plan_State IN (1,2,4,5,6,8,9) THEN 1 ELSE 0 END AS underApprovalCount FROM Gantt_Plan mn LEFT JOIN Gantt_Plan_Template gpt ON gpt.pt_id = mn.pt_id LEFT JOIN Con_Contract con ON con.Con_Id = mn.Con_Id LEFT JOIN SYS_Department dep ON dep.D_ID = mn.Plan_D_Id
LEFT JOIN SYS_Department d2 ON pro.P_Department = d2.D_Id LEFT JOIN Sec_Info sec ON sec.Sec_Id = mn.Sec_Id LEFT JOIN ( SELECT gt.Plan_Id, SUM(CASE WHEN gt.task_importance = '99' THEN 1 ELSE 0 END) AS milestoneCount, SUM(CASE WHEN gt.task_importance = '01' THEN 1 ELSE 0 END) AS firstLevelCount, SUM(CASE WHEN gt.task_importance = '02' THEN 1 ELSE 0 END) AS secondLevelCount FROM Gantt_Tasks gt WHERE gt.task_importance IN ('99','01','02') GROUP BY gt.Plan_Id ) gtc ON gtc.Plan_Id = mn.Plan_Id ${params.authSql}
ORDER BY mn.${params.sortFiled} ${params.sortType}
ORDER BY ${params.sortSideFiled} ${params.sortType}
ORDER BY CASE mn.plan_state WHEN 3 THEN 99 ELSE mn.plan_state END, CASE WHEN mn.plan_state = 0 THEN mn.plan_create_time ELSE mn.plan_state_time END DESC

SELECT ps.alreadyOver, ps.notStart, ps.underApproval, COALESCE(ts.milestoneCount, 0) AS milestoneCount, COALESCE(ts.firstLevelCount, 0) AS firstLevelCount, COALESCE(ts.secondLevelCount, 0) AS secondLevelCount FROM ( SELECT SUM(CASE WHEN mn.plan_state = 7 THEN 1 ELSE 0 END) AS alreadyOver, SUM(CASE WHEN mn.plan_state = 0 THEN 1 ELSE 0 END) AS notStart, SUM(CASE WHEN mn.plan_state IN (1,2,4,5,6,8,9) THEN 1 ELSE 0 END) AS underApproval FROM Gantt_Plan mn LEFT JOIN Gantt_Plan_Template gpt ON gpt.pt_id = mn.pt_id LEFT JOIN Con_Contract con ON con.Con_Id = mn.Con_Id LEFT JOIN SYS_Department dep ON dep.D_ID = mn.Plan_D_Id
LEFT JOIN SYS_Department d2 ON pro.P_Department = d2.D_Id LEFT JOIN Sec_Info sec ON sec.Sec_Id = mn.Sec_Id ${params.authSql}
) ps CROSS JOIN ( SELECT SUM(CASE WHEN gt.task_importance = '99' THEN 1 ELSE 0 END) AS milestoneCount, SUM(CASE WHEN gt.task_importance = '01' THEN 1 ELSE 0 END) AS firstLevelCount, SUM(CASE WHEN gt.task_importance = '02' THEN 1 ELSE 0 END) AS secondLevelCount FROM Gantt_Tasks gt WHERE gt.task_importance IN ('99','01','02') AND EXISTS ( SELECT 1 FROM Gantt_Plan mn LEFT JOIN Gantt_Plan_Template gpt ON gpt.pt_id = mn.pt_id LEFT JOIN Con_Contract con ON con.Con_Id = mn.Con_Id LEFT JOIN SYS_Department dep ON dep.D_ID = mn.Plan_D_Id
LEFT JOIN SYS_Department d2 ON pro.P_Department = d2.D_Id LEFT JOIN Sec_Info sec ON sec.Sec_Id = mn.Sec_Id ${params.authSql}
and mn.Plan_Id = gt.Plan_Id )) ts

select
con.Con_Name as conName, dep.D_Name as dName, sec.Sec_Name as secName, gpt.Pt_Name as ptName, mn.*, pro.P_Department as pDepartment, d2.D_Name as pDepartmentName, (select count(*) from Gantt_Tasks_Process gtp join Gantt_Tasks gt on gtp.Task_Id = gt.Task_Id where gt.Plan_Id = mn.Plan_Id and gt.Task_Type != '01' and gtp.Gtp_State = 7 and gtp.Gtp_Id = ( select gtp2.Gtp_Id from Gantt_Tasks_Process gtp2 where gtp2.Task_Id = gtp.Task_Id order by gtp2.Gtp_upload_times desc limit 1)) as alreadyOverCount, (select count(*) from Gantt_Tasks_Process gtp join Gantt_Tasks gt on gtp.Task_Id = gt.Task_Id where gt.Plan_Id = mn.Plan_Id and gt.Task_Type != '01' and gtp.Gtp_State not in (0, 3, 7) and gtp.Gtp_Id = ( select gtp2.Gtp_Id from Gantt_Tasks_Process gtp2 where gtp2.Task_Id = gtp.Task_Id order by gtp2.Gtp_upload_times desc limit 1)) as underApprovalCount, (select count(*) from Gantt_Tasks gt where gt.Plan_Id = mn.Plan_Id and gt.Task_Type != '01' and gt.Must_Handle = 1) as mustHandleCount, (select count(*) from Gantt_Tasks gt where gt.Plan_Id = mn.Plan_Id and gt.Task_Type != '01' and gt.task_importance = '99') as milestoneCount, (select count(*) from Gantt_Tasks gt where gt.Plan_Id = mn.Plan_Id and gt.Task_Type != '01' and gt.task_importance = '01') as firstLevelCount, (select count(*) from Gantt_Tasks gt where gt.Plan_Id = mn.Plan_Id and gt.Task_Type != '01' and gt.task_importance = '02') as secondLevelCount from Gantt_Plan mn left join Gantt_Plan_Template gpt on gpt.pt_id=mn.pt_id left join Con_Contract con on con.Con_Id=mn.Con_Id left join SYS_Department dep on dep.D_ID=mn.Plan_D_Id
left join SYS_Department d2 on pro.P_Department = d2.D_Id left join Sec_Info sec on sec.Sec_Id=mn.Sec_Id ${params.authSql}
